{
  "mechanisms": [
    {
      "name": "asymmetric_learning_rates",
      "title": "Asymmetric Learning Rates",
      "description": "Separate learning rates are used for positive and negative prediction errors at both stages.",
      "params": [
        {
          "name": "alpha_pos",
          "bounds": [0, 1]
        },
        {
          "name": "alpha_neg",
          "bounds": [0, 1]
        }
      ],
      "evidence": "alpha_s1 = alpha_pos if delta_stage1 > 0 else alpha_neg\n        q_stage1_mf[act1] += alpha_s1 * delta_stage1\n\n        delta_stage2 = reward[trial] - q_stage2_mf[state_idx, act2]\n        alpha_s2 = alpha_pos if delta_stage2 > 0 else alpha_neg\n        q_stage2_mf[state_idx, act2] += alpha_s2 * delta_stage2",
      "expressible_in_slots": true
    },
    {
      "name": "mb_mf_mixture",
      "title": "MB/MF Mixture Weight",
      "description": "Stage 1 values are computed as a weighted mixture of model-based and model-free Q-values.",
      "params": [
        {
          "name": "w",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_net = w * q_stage1_mb + (1 - w) * q_stage1_mf",
      "expressible_in_slots": true
    },
    {
      "name": "transition_dependent_perseveration",
      "title": "Transition-Dependent Perseveration",
      "description": "A perseveration bonus is applied to the previously chosen stage 1 action, with the magnitude depending on whether the previous trial's transition was common or rare.",
      "params": [
        {
          "name": "pi_common",
          "bounds": [-5, 5]
        },
        {
          "name": "pi_rare",
          "bounds": [-5, 5]
        }
      ],
      "evidence": "if last_trans_common == 1:\n            pi = pi_common\n        elif last_trans_common == 0:\n            pi = pi_rare\n        else:\n            pi = 0.0\n            \n        logits1 = beta1 * (q_stage1_net + pi * rep)",
      "expressible_in_slots": true
    },
    {
      "name": "unchosen_decay",
      "title": "Unchosen Value Decay",
      "description": "Model-free Q-values for unchosen actions and unvisited states decay towards zero on each trial.",
      "params": [
        {
          "name": "decay",
          "bounds": [0, 1]
        }
      ],
      "evidence": "unchosen_1 = 1 - act1\n        q_stage1_mf[unchosen_1] *= (1 - decay)\n        \n        unchosen_2 = 1 - act2\n        q_stage2_mf[state_idx, unchosen_2] *= (1 - decay)\n        \n        other_state = 1 - state_idx\n        q_stage2_mf[other_state, 0] *= (1 - decay)\n        q_stage2_mf[other_state, 1] *= (1 - decay)",
      "expressible_in_slots": true
    }
  ]
}
